WITH store_part AS (SELECT sr.sr_reason_sk AS reason_sk, sr.sr_net_loss AS net_loss, sr.sr_customer_sk AS customer_sk, CAST(NULL AS VARCHAR) AS page_type FROM store_returns sr), web_part AS (SELECT wr.wr_reason_sk AS reason_sk, wr.wr_net_loss AS net_loss, wr.wr_refunded_customer_sk AS customer_sk, wp.wp_type AS page_type FROM web_returns wr JOIN web_page wp ON wr.wr_web_page_sk = wp.wp_web_page_sk), combined_returns AS (SELECT * FROM store_part UNION ALL SELECT * FROM web_part) SELECT cr.reason_sk, COUNT(*) AS total_returns, SUM(cr.net_loss) AS total_net_loss, CASE WHEN cr.reason_sk BETWEEN 1 AND 5 THEN 'Damaged' WHEN cr.reason_sk BETWEEN 6 AND 10 THEN 'Incorrect Item' WHEN cr.reason_sk BETWEEN 11 AND 15 THEN 'Late Delivery' ELSE 'Other' END AS reason_category, COUNT(DISTINCT cr.page_type) AS distinct_page_types, RANK() OVER (ORDER BY SUM(cr.net_loss) DESC) AS loss_rank, CUME_DIST() OVER (ORDER BY SUM(cr.net_loss) DESC) AS cumulative_dist FROM combined_returns cr JOIN customer c ON cr.customer_sk = c.c_customer_sk WHERE c.c_birth_country = 'USA' GROUP BY cr.reason_sk ORDER BY total_net_loss DESC LIMIT 10
